// Stylelint for src/cms/frontend (F050 T019, F050-AC-06, TC-UI-003, AGENTS R32): no color, font, font size or
// spacing literal in CSS; use var(--ew-*) from the generated tokens.css. Generated token files are ignored.
const TOKEN = 'var\\(--ew-[a-z0-9-]+\\)';
const tokenList = (extra) => new RegExp(`^((${TOKEN}|${extra})\\s*)+$`);

export default {
  extends: ['stylelint-config-standard'],
  ignoreFiles: [
    '**/node_modules/**',
    '**/dist/**',
    '**/storybook-static/**',
    // generated by design/ (make design-tokens)
    'packages/ops-ui/src/theme/tokens.css',
  ],
  rules: {
    'color-no-hex': true,
    'color-named': 'never',
    'function-disallowed-list': ['rgb', 'rgba', 'hsl', 'hsla', 'hwb', 'lab', 'lch', 'oklab', 'oklch'],
    'declaration-property-value-allowed-list': {
      '/^(margin|padding|gap|row-gap|column-gap)(-|$)/': [tokenList('0|auto|inherit')],
      'font-size': [tokenList('inherit')],
      'font-family': [tokenList('inherit')],
      font: [tokenList('inherit')],
      'line-height': [tokenList('inherit|normal|1')],
      'letter-spacing': [tokenList('inherit|normal')],
    },
  },
  overrides: [
    {
      // @font-face declares the self-hosted families (DESIGN_SYSTEM §4.1, design/fonts)
      files: ['**/fonts.css'],
      rules: { 'declaration-property-value-allowed-list': null },
    },
  ],
};
